/// <summary>
/// class <c>METTelemetryTransferOrderPickedInfoEvent</c> is used to log error event whenever transfer order info event.
/// </summary>
internal final class METTelemetryTransferOrderPickedInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryTransferOrderPickedInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryTransferOrderPickedInfoEvent</c> </returns>
public static METTelemetryTransferOrderPickedInfoEvent construct()
{
    return new METTelemetryTransferOrderPickedInfoEvent();
}

/// <summary>
/// Run transfer order telmetry log
/// </summary>
/// <param name = "_transferId"> table <c>transferId</c> </param>
public static void runTelemetryEvent(InventTransferId _transferId)
{
    METTelemetryTransferOrderPickedInfoEvent transferOrderPickEvent = METTelemetryTransferOrderPickedInfoEvent::construct();

    transferOrderPickEvent.addRunTimePropertyToAppinsights(_transferId);

    transferOrderPickEvent.processEvent(METTelemetryEventNames::TOPickedInfoEvent);
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_transferId"> table <c>transferId</c> </param>
public void addRunTimePropertyToAppinsights(InventTransferid _transferId)
{
    InventTransferTable inventTransferTable = InventTransferTable::find(_transferId);
    METInventTransferTableExt inventTransferTableExt = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId);

    this.addRuntimeProperty('TransferId', inventTransferTable.TransferId);
    this.addRuntimeProperty('FromWarehouseId' ,inventTransferTable.InventLocationIdFrom);
    this.addRuntimeProperty('ToWarehouseId', inventTransferTable.InventLocationIdTo);
    this.addRuntimeProperty('TransferType', enum2Str(inventTransferTableExt.TransferType));
    this.addRuntimeProperty('OrderSplitGroup', inventTransferTableExt.OrderSplitGroup);
}
